import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { Button, Text, View } from 'react-native';

const lessons = [
  { id: 'a1', title: 'Первый шаг' },
  { id: 'a2', title: 'Повторение' },
];

function ListScreen({ navigation }: { navigation: { navigate: (name: string, params?: { id: string }) => void } }) {
  return (
    <View style={{ flex: 1, padding: 24, gap: 12 }}>
      {lessons.map(lesson => (
        <Button key={lesson.id} title={lesson.title} onPress={() => navigation.navigate('Details', { id: lesson.id })} />
      ))}
    </View>
  );
}

